window.VF1_UNITS = {"14":{"unit":14,"code":"VF1-U14","title":"Problems & Solutions","startNumber":353,"endNumber":381,"entries":[{"number":353,"term":"assume ~ suppose · assumption","sourceTerm":"assume (v) ~ suppose (v) · assumption (n)","spoken":"assume ~ suppose · assumption","ipa":"/əˈsuːm səˈpoʊz əˈsʌmpʃən/","type":"verb · noun","meaning":"cho là đúng khi chưa có bằng chứng ~ cho rằng/giả sử · giả định","definition":"To accept something as true without proof; an idea accepted without proof.","note":"assume nghĩa là cho là đúng khi chưa có bằng chứng; suppose thường là suy đoán dè dặt hoặc đặt giả thiết.","example":"We assume, or suppose, that the bus will arrive on time, but this assumption may be wrong."},{"number":354,"term":"claim","sourceTerm":"claim (v,n)","spoken":"claim","ipa":"/kleɪm/","type":"verb · noun","meaning":"khẳng định/tuyên bố · lời khẳng định; yêu cầu","definition":"To say that something is true, or such a statement; to ask formally for something you believe you should receive.","note":"claim dùng được như động từ và danh từ.","example":"The company claims that the bag lasts ten years, but this claim still needs evidence."},{"number":355,"term":"complain to sb about st · complaint","sourceTerm":"complain (v) to sb about st · complaint (n)","spoken":"complain to somebody about something · complaint","ipa":"/kəˈmpleɪn tuː ˈsʌˌmbɑːdi əˈbaʊt ˈsʌmθɪŋ kəˈmpleɪnt/","type":"verb · noun","meaning":"phàn nàn với ai về điều gì · lời/sự phàn nàn","definition":"To express dissatisfaction; a statement of dissatisfaction.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: complain (v) to sb about st · complaint (n)","example":"Mai complained to the shop about the broken bottle and made a clear complaint."},{"number":356,"term":"convince sb that… ~ persuade sb to do…","sourceTerm":"convince (v) sb that… ~ persuade (v) sb to do…","spoken":"convince somebody that… ~ persuade somebody to do…","ipa":"/kəˈnvɪns ˈsʌˌmbɑːdi ðæt pɚˈsweɪd ˈsʌˌmbɑːdi tuː duː/","type":"verb","meaning":"thuyết phục ai tin rằng… ~ thuyết phục ai làm gì","definition":"To make someone believe or agree.","note":"convince sb that…: khiến ai tin; persuade sb to do…: thuyết phục ai hành động.","example":"The evidence convinced me, and the teacher persuaded the class to check it carefully."},{"number":357,"term":"discuss · discussion","sourceTerm":"discuss (v) · discussion (n)","spoken":"discuss · discussion","ipa":"/dɪˈskʌs dɪˈskʌʃən/","type":"verb · noun","meaning":"thảo luận · cuộc/sự thảo luận","definition":"To talk about a subject; a conversation about it.","note":"","example":"The group discussed the problem, and the discussion produced two simple ideas."},{"number":358,"term":"criticize · critical · criticism","sourceTerm":"criticize (v) · critical (a) · criticism (n)","spoken":"criticize · critical · criticism","ipa":"/ˈkrɪtɪˌsaɪz ˈkrɪtɪkəl ˈkrɪtɪˌsɪzəm/","type":"verb · noun · adjective","meaning":"chỉ trích · mang tính phê bình/chỉ trích · sự/lời chỉ trích","definition":"To express disapproval; judging carefully; an unfavourable comment.","note":"","example":"The teacher criticized the unclear answer; her critical comment was fair, and the criticism helped me improve it."},{"number":359,"term":"praise","sourceTerm":"praise (v,n)","spoken":"praise","ipa":"/preɪz/","type":"verb · noun","meaning":"ca ngợi · lời khen; sự ca ngợi","definition":"To express approval or admiration; words that express approval or admiration.","note":"praise dùng được như động từ và danh từ.","example":"The teacher praised Lan for her careful work, and the praise encouraged her to continue."},{"number":360,"term":"doubt","sourceTerm":"doubt (v,n)","spoken":"doubt","ipa":"/daʊt/","type":"verb · noun","meaning":"nghi ngờ","definition":"To feel uncertain about something; uncertainty.","note":"","example":"I doubt that the plan will work without more time."},{"number":361,"term":"encourage sb to do st · encouragement >< discourage sb from doing st","sourceTerm":"encourage (v) sb to do st · encouragement (n) >< discourage (v) sb from doing st","spoken":"encourage somebody to do something · encouragement >< discourage somebody from doing something","ipa":"/ɛˈnkɝːɪdʒ ˈsʌˌmbɑːdi tuː duː ˈsʌmθɪŋ ɛˈnkɝːɪdʒmənt dɪˈskɝːɪdʒ ˈsʌˌmbɑːdi frʌm ˈduːɪŋ ˈsʌmθɪŋ/","type":"verb · noun","meaning":"khuyến khích ai làm gì · sự khuyến khích >< ngăn/nản ai làm gì","definition":"To give support and confidence; support; to reduce confidence.","note":"encourage sb to do; discourage sb from doing. Hai động từ dùng hai giới từ/cấu trúc khác nhau.","example":"The coach encouraged us to keep trying, and his encouragement helped; he discouraged us from giving up."},{"number":362,"term":"get rid of st","sourceTerm":"get rid of st","spoken":"get rid of something","ipa":"/ɡɛt rɪd ʌv ˈsʌmθɪŋ/","type":"phrase / pattern","meaning":"thoát khỏi, vứt bỏ…","definition":"To remove or throw away something unwanted.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: get rid of st","example":"The town wants to get rid of plastic waste by using fewer bags."},{"number":363,"term":"ideal","sourceTerm":"ideal (a)","spoken":"ideal","ipa":"/aɪˈdiːl/","type":"adjective","meaning":"lí tưởng","definition":"Perfect or most suitable.","note":"","example":"An ideal study plan is clear, practical, and easy to follow."},{"number":364,"term":"investigate · investigation","sourceTerm":"investigate (v) · investigation (n)","spoken":"investigate · investigation","ipa":"/ˌɪˈnvɛstəˌɡeɪt ˌɪˌnvɛstəˈɡeɪʃən/","type":"verb · noun","meaning":"điều tra/nghiên cứu · cuộc/sự điều tra","definition":"To examine facts carefully; a careful official examination.","note":"","example":"The school investigated the missing books, and the investigation found them in another room."},{"number":365,"term":"positive >< negative","sourceTerm":"positive (a) >< negative (a)","spoken":"positive >< negative","ipa":"/ˈpɑːzətɪv ˈnɛɡətɪv/","type":"adjective","meaning":"tích cực >< tiêu cực","definition":"Helpful or confident; harmful or unfavourable.","note":"Chú ý cặp đối lập hoặc điểm khác nhau được đánh dấu trong danh sách. Cách kết hợp: positive (a) >< negative (a)","example":"The plan has both positive and negative effects."},{"number":366,"term":"pretend to do st","sourceTerm":"pretend (v) to do st","spoken":"pretend to do something","ipa":"/priˈtɛnd tuː duː ˈsʌmθɪŋ/","type":"verb","meaning":"giả vờ","definition":"To behave as if something is true when it is not.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: pretend (v) to do st","example":"He pretended to understand the task instead of asking for help."},{"number":367,"term":"refuse to do st · refusal","sourceTerm":"refuse (v) to do st · refusal (n)","spoken":"refuse to do something · refusal","ipa":"/rəˈfjuːz tuː duː ˈsʌmθɪŋ rəˈfjuːzəl/","type":"verb · noun","meaning":"từ chối làm gì · sự/lời từ chối","definition":"To say that you will not do something; an act of refusing.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: refuse (v) to do st · refusal (n)","example":"The shop refused to replace the bag, and its refusal disappointed the customer."},{"number":368,"term":"deny doing st","sourceTerm":"deny (v) doing st","spoken":"deny doing something","ipa":"/dɪˈnaɪ ˈduːɪŋ ˈsʌmθɪŋ/","type":"verb","meaning":"phủ nhận đã làm gì","definition":"To say that you did not do something.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: deny (v) doing st","example":"The student denied copying the answer and asked the teacher to check her work."},{"number":369,"term":"rumour","sourceTerm":"rumour (n)","spoken":"rumour","ipa":"/ˈruːmɚ/","type":"noun","meaning":"lời đồn; tin đồn","definition":"Unconfirmed information passed from one person to another that may not be true.","note":"rumour là danh từ; động từ tương ứng thường dùng spread a rumour.","example":"A false rumour spread quickly through the class group, although nobody could confirm it."},{"number":370,"term":"theory >< practice · theoretical","sourceTerm":"theory (n) >< practice (n) · theoretical (a)","spoken":"theory >< practice · theoretical","ipa":"/ˈθɪri ˈpræktəs ˌθiɚˈɛtɪkəl/","type":"noun · adjective","meaning":"lí thuyết >< việc áp dụng thực tế · thuộc lí thuyết","definition":"An explanation of ideas; actual use or action; based on ideas rather than action.","note":"theory nghĩa là hệ thống ý tưởng/lí thuyết; practice nghĩa là việc áp dụng thực tế; theoretical là tính từ.","example":"The theory sounds reasonable, but we need to test it in practice; the theoretical idea may work differently in real life."},{"number":371,"term":"advise · advice","sourceTerm":"advise (v) · advice (n)","spoken":"advise · advice","ipa":"/æˈdvaɪz æˈdvaɪs/","type":"verb · noun","meaning":"khuyên · lời khuyên","definition":"To recommend an action; a recommendation.","note":"","example":"Teachers advise students to plan their time and ask for advice when necessary."},{"number":372,"term":"pressure · under pressure","sourceTerm":"pressure (n) · under pressure","spoken":"pressure · under pressure","ipa":"/ˈprɛʃɚ ˈʌndɚ ˈprɛʃɚ/","type":"noun","meaning":"áp lực/sức ép · đang chịu áp lực","definition":"Stress caused by demands; in a stressful situation.","note":"","example":"People often make poor decisions when they are under pressure."},{"number":373,"term":"mess · messy · in a mess","sourceTerm":"mess (n) · messy (a) · in a mess","spoken":"mess · messy · in a mess","ipa":"/mɛs ˈmɛsi ɪn ə mɛs/","type":"noun · adjective","meaning":"tình trạng/đống lộn xộn · lộn xộn/bừa bộn · đang trong tình trạng lộn xộn","definition":"A dirty or untidy state; untidy.","note":"","example":"The room was in a mess because messy papers were left everywhere."},{"number":374,"term":"in my view ~ in my opinion # in trouble","sourceTerm":"in my view ~ in my opinion # in trouble","spoken":"in my view ~ in my opinion # in trouble","ipa":"/ɪn maɪ vjuː ɪn maɪ əˈpɪnjən ɪn ˈtrʌbəl/","type":"phrase / pattern","meaning":"theo quan điểm của tôi # đang gặp rắc rối","definition":"From my point of view; in a difficult situation.","note":"in my view và in my opinion cùng nêu quan điểm. in trouble là cụm riêng, nghĩa là đang gặp rắc rối.","example":"In my view, or in my opinion, the team is in trouble because it has too little time."},{"number":375,"term":"except · exception · exceptional","sourceTerm":"except · exception (n) · exceptional (a)","spoken":"except · exception · exceptional","ipa":"/ɪˈksɛpt ɪˈksɛpʃən ɪˈksɛpʃənəl/","type":"noun · adjective","meaning":"ngoại trừ · ngoại lệ · đặc biệt/xuất sắc","definition":"Not including; something that does not follow the rule; unusually excellent.","note":"","example":"Everyone except Nam agreed; his choice was the only exception, but his work was exceptional."},{"number":376,"term":"preference","sourceTerm":"preference (n)","spoken":"preference","ipa":"/ˈprɛfɚəns/","type":"noun","meaning":"sở thích, khuynh hướng (thích cái gì hơn)","definition":"A greater liking for one option.","note":"","example":"The survey records students' preferences for different learning activities."},{"number":377,"term":"approve of st ~ agree with st >< disapprove of st · approval >< disapproval","sourceTerm":"approve (v) of st ~ agree with st >< disapprove (v) of st · approval (n) >< disapproval (n)","spoken":"approve of something ~ agree with something >< disapprove of something · approval >< disapproval","ipa":"/əˈpruːv ʌv ˈsʌmθɪŋ əˈɡriː wɪð ˈsʌmθɪŋ ˌdɪsəˈpruːv ʌv ˈsʌmθɪŋ əˈpruːvəl dɪsəˈpruːvəl/","type":"verb · noun","meaning":"tán thành/cho là tốt ~ đồng ý/cùng ý kiến >< không tán thành · sự tán thành >< sự không tán thành","definition":"To agree with; to disagree with; agreement or disagreement.","note":"approve of nghĩa là cho là tốt/ủng hộ; agree with nghĩa là cùng ý kiến với; disapprove of nghĩa là không tán thành.","example":"Most parents approve of and agree with the change, while a few disapprove of it; the plan received more approval than disapproval."},{"number":378,"term":"insist on doing st","sourceTerm":"insist (v) on doing st","spoken":"insist on doing something","ipa":"/ˌɪˈnsɪst ɑːn ˈduːɪŋ ˈsʌmθɪŋ/","type":"verb","meaning":"khăng khăng làm gì","definition":"To demand something firmly.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: insist (v) on doing st","example":"She insisted on checking every number before sending the report."},{"number":379,"term":"recommend ~ suggest · recommendation ~ suggestion","sourceTerm":"recommend (v) ~ suggest (v) · recommendation (n) ~ suggestion (n)","spoken":"recommend ~ suggest · recommendation ~ suggestion","ipa":"/ˌrɛkəˈmɛnd səˈdʒɛst ˌrɛkəməˈndeɪʃən səˈdʒɛstʃən/","type":"verb · noun","meaning":"đề xuất/gợi ý · lời đề xuất/gợi ý","definition":"To advise a suitable action; an advised action.","note":"recommend và suggest đều đi với danh từ, V-ing hoặc that-clause; không dùng suggest sb to do.","example":"The teacher recommended, or suggested, a simpler plan; her recommendation and suggestion helped the class."},{"number":380,"term":"run out of st","sourceTerm":"run out of st","spoken":"run out of something","ipa":"/rʌn aʊt ʌv ˈsʌmθɪŋ/","type":"phrasal verb","meaning":"cạn kiệt cái gì","definition":"To use all of something so none remains.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: run out of st","example":"The village ran out of clean water during the long dry period."},{"number":381,"term":"work out ~ figure out # sort out # find out","sourceTerm":"work out ~ figure out # sort out # find out","spoken":"work out ~ figure out # sort out # find out","ipa":"/wɝːk aʊt ˈfɪɡjɚ aʊt sɔːrt aʊt faɪnd aʊt/","type":"phrasal verb","meaning":"tìm ra lời giải/hiểu ra # xử lí/sắp xếp ổn thỏa # phát hiện thông tin","definition":"To find a solution or understand the answer.","note":"work out/figure out nghĩa là tìm ra cách hiểu/giải; sort out nghĩa là sắp xếp hoặc xử lí ổn thỏa; find out nghĩa là khám phá thông tin.","example":"After several tests, the team worked out, sorted out, and figured out the problem; it then found out who could fix it."}],"pronunciationFocus":[{"entryNumber":353,"points":[{"category":"word-stress","note":"assume và suppose nhấn âm hai; assumption nhấn vào /ˈsʌmp/"}]},{"entryNumber":357,"points":[{"category":"common-error","note":"discuss kết thúc bằng /s/; discussion có phần cuối /ʃən/"},{"category":"final-sound","note":"Giữ /s/ ở cuối discuss; không đổi thành /z/"}]},{"entryNumber":360,"points":[{"category":"silent-letter","note":"Chữ b trong doubt không được phát âm"},{"category":"final-sound","note":"doubt kết thúc trực tiếp bằng /t/"}]},{"entryNumber":364,"points":[{"category":"word-stress","note":"investigate nhấn vào /ˈvɛs/; investigation chuyển trọng âm sang /ˈɡeɪ/"}]},{"entryNumber":370,"points":[{"category":"word-stress","note":"theory nhấn âm đầu; theoretical chuyển trọng âm sang âm tiết chứa /ɛt/"}]},{"entryNumber":371,"points":[{"category":"common-error","note":"advise kết thúc bằng /z/, còn advice kết thúc bằng /s/"},{"category":"final-sound","note":"Giữ rõ sự đối lập /z/ và /s/ ở cuối hai từ"}]},{"entryNumber":379,"points":[{"category":"word-stress","note":"recommend nhấn vào /ˈmɛnd/; recommendation chuyển trọng âm sang /ˈdeɪ/"}]},{"entryNumber":381,"points":[{"category":"linking","note":"Trong work‿out, sort‿out và find‿out, nối phụ âm cuối /k/, /t/ hoặc /d/ sang nguyên âm /aʊ/ của out"}]}]}};
